package org.sleepwell.app;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public final class PhoneTorchCoordinatorTest {
 final List<Boolean> commands=new ArrayList<>();final boolean[] live={true};final PhoneTorchCoordinator broker=new PhoneTorchCoordinator(commands::add);
 static final class Events implements PhoneTorchCoordinator.Events{PhoneTorchCoordinator.Lease lease;String lost="";int ready;public void ready(PhoneTorchCoordinator.Lease value){lease=value;ready++;}public void lost(String reason){lost=reason;}}
 Events acquire(PhoneTorchCoordinator.Kind kind){Events e=new Events();broker.acquire(kind,()->live[0],e);return e;}
 @Test public void unknownAndUnavailableDoNotTouchLight(){Events e=acquire(PhoneTorchCoordinator.Kind.TRAVEL);assertEquals(0,e.ready);assertFalse(e.lost.isEmpty());broker.unavailable();assertFalse(acquire(PhoneTorchCoordinator.Kind.ALARM).lost.isEmpty());assertTrue(commands.isEmpty());}
 @Test public void experimentalLeaseWaitsForExplicitPulse(){broker.observed(false);Events e=acquire(PhoneTorchCoordinator.Kind.TRAVEL);assertEquals(1,e.ready);assertTrue(commands.isEmpty());e.lease.set(true);assertEquals(List.of(true),commands);broker.observed(true);e.lease.set(false);assertEquals(List.of(true,false),commands);broker.observed(false);e.lease.close();assertEquals(2,commands.size());}
 @Test public void alarmKeepsSteadySemanticsAndOnlyReleasesItsOwnRequest(){broker.observed(false);Events e=acquire(PhoneTorchCoordinator.Kind.ALARM);assertEquals(List.of(true),commands);broker.observed(true);e.lease.close();e.lease.close();assertEquals(List.of(true,false),commands);}
 @Test public void externallyLitTorchIsNeitherBorrowedNorExtinguishedByTravel(){broker.observed(true);assertEquals(0,acquire(PhoneTorchCoordinator.Kind.TRAVEL).ready);assertTrue(commands.isEmpty());}
 @Test public void alarmPreservesAlreadyLitExternalTorch(){broker.observed(true);Events e=acquire(PhoneTorchCoordinator.Kind.ALARM);e.lease.close();assertTrue(commands.isEmpty());}
 @Test public void alarmPreemptsTravelBeforeFirstAlarmOnAndStaleOffNeverRuns(){broker.observed(false);Events travel=acquire(PhoneTorchCoordinator.Kind.TRAVEL);travel.lease.set(true);broker.observed(true);Events alarm=acquire(PhoneTorchCoordinator.Kind.ALARM);assertEquals(List.of(true,false,true),commands);assertFalse(travel.lost.isEmpty());travel.lease.set(false);travel.lease.set(true);travel.lease.close();assertEquals(List.of(true,false,true),commands);broker.observed(false);broker.observed(true);assertEquals(1,alarm.ready);assertEquals(3,commands.size());alarm.lease.close();assertEquals(List.of(true,false,true,false),commands);}
 @Test public void travelCannotPreemptAnAlarm(){broker.observed(false);Events alarm=acquire(PhoneTorchCoordinator.Kind.ALARM);Events travel=acquire(PhoneTorchCoordinator.Kind.TRAVEL);assertEquals(0,travel.ready);assertFalse(travel.lost.isEmpty());assertEquals(List.of(true),commands);alarm.lease.close();}
 @Test public void externalOffIsNotFoughtByAlarm(){broker.observed(false);Events alarm=acquire(PhoneTorchCoordinator.Kind.ALARM);broker.observed(true);broker.observed(false);alarm.lease.close();assertEquals(List.of(true),commands);}
 @Test public void externalOffRevokesTravelAndCannotReviveItsGeneration(){broker.observed(false);Events e=acquire(PhoneTorchCoordinator.Kind.TRAVEL);e.lease.set(true);broker.observed(true);broker.observed(false);assertFalse(e.lost.isEmpty());e.lease.set(true);e.lease.close();broker.observed(false);assertEquals(List.of(true),commands);assertTrue(broker.idle());}
 @Test public void lateOwnOnWhileOffAcknowledgmentPendingDoesNotCreateAnotherCommand(){broker.observed(false);Events e=acquire(PhoneTorchCoordinator.Kind.TRAVEL);e.lease.set(true);e.lease.set(false);broker.observed(true);assertEquals("",e.lost);broker.observed(false);e.lease.set(true);assertEquals(List.of(true,false,true),commands);}
 @Test public void unrequestedOnAfterOffAcknowledgmentIsNotExtinguished(){broker.observed(false);Events e=acquire(PhoneTorchCoordinator.Kind.TRAVEL);broker.observed(true);assertFalse(e.lost.isEmpty());e.lease.close();assertTrue(commands.isEmpty());}
 @Test public void livenessLossBeforeAcquireOrOnPreventsActivation(){broker.observed(false);live[0]=false;assertEquals(0,acquire(PhoneTorchCoordinator.Kind.ALARM).ready);assertTrue(commands.isEmpty());live[0]=true;Events e=acquire(PhoneTorchCoordinator.Kind.TRAVEL);live[0]=false;e.lease.set(true);assertTrue(commands.isEmpty());assertTrue(broker.idle());}
 @Test public void unavailableDoesNotSendOffToUnownedCamera(){broker.observed(false);Events e=acquire(PhoneTorchCoordinator.Kind.TRAVEL);e.lease.set(true);broker.unavailable();e.lease.close();assertEquals(List.of(true),commands);assertFalse(e.lost.isEmpty());}
 @Test public void failedOnFailsExplicitlyAndBestEffortReleasesPendingRequest(){List<Boolean> calls=new ArrayList<>();PhoneTorchCoordinator failing=new PhoneTorchCoordinator(on->{calls.add(on);if(on)throw new IllegalStateException();});failing.observed(false);Events e=new Events();assertNull(failing.acquire(PhoneTorchCoordinator.Kind.ALARM,()->true,e));assertFalse(e.lost.isEmpty());assertEquals(List.of(true,false),calls);assertTrue(failing.idle());}
 @Test public void failedReleaseIsNeverReportedAsCleanFinish(){PhoneTorchCoordinator failing=new PhoneTorchCoordinator(on->{if(!on)throw new IllegalStateException();});failing.observed(false);Events e=new Events();failing.acquire(PhoneTorchCoordinator.Kind.ALARM,()->true,e);e.lease.close();assertEquals("The flashlight could not be released.",e.lost);assertTrue(failing.idle());}
}
